package com.mahweb.mahyarnfc.omnishare.ble;
import android.bluetooth.*; import android.bluetooth.le.*; import android.content.Context; import android.os.ParcelUuid; import java.util.*;
public final class BleScanner implements AutoCloseable { public interface Listener{void onObservation(BleObservation o);void onError(int code,String message);} private final Context ctx;private final Listener listener;private BluetoothLeScanner scanner;private ScanCallback cb;
 public BleScanner(Context c,Listener l){ctx=c.getApplicationContext();listener=l;}
 public void start(){try{BluetoothManager m=(BluetoothManager)ctx.getSystemService(Context.BLUETOOTH_SERVICE);BluetoothAdapter a=m==null?null:m.getAdapter();scanner=a==null?null:a.getBluetoothLeScanner();if(scanner==null){err(-1,"BLE scan unavailable");return;}ScanFilter f=new ScanFilter.Builder().setServiceUuid(new ParcelUuid(BleProtocol.SERVICE_UUID)).build();ScanSettings s=new ScanSettings.Builder().setScanMode(ScanSettings.SCAN_MODE_LOW_LATENCY).build();cb=new ScanCallback(){public void onScanResult(int type,ScanResult r){handle(r);}public void onBatchScanResults(List<ScanResult>rs){for(ScanResult r:rs)handle(r);}public void onScanFailed(int e){err(e,"BLE scan failed");}};scanner.startScan(Collections.singletonList(f),s,cb);}catch(SecurityException e){err(-2,"Bluetooth scan permission denied");}}
 private void handle(ScanResult r){ScanRecord rec=r.getScanRecord();if(rec==null)return;byte[]d=rec.getServiceData(new ParcelUuid(BleProtocol.SERVICE_UUID));BleProtocol.Parsed p=BleProtocol.parse(d);if(p==null)return;StringBuilder h=new StringBuilder();for(byte x:p.token)h.append(String.format(Locale.US,"%02x",x));if(listener!=null)listener.onObservation(new BleObservation(h.toString(),r.getRssi(),System.currentTimeMillis(),p.capabilities));}
 private void err(int c,String m){if(listener!=null)listener.onError(c,m);} public void close(){if(scanner!=null&&cb!=null)try{scanner.stopScan(cb);}catch(SecurityException ignored){}cb=null;}
}
